use xiom.io;

use xiom.string;
fn my_min[T](a: T, b: T) -> T {
  if a < b { return a; }
  else { return b; }
}

fn main() -> Int {
  let int_result = my_min(5, 3);
  io.println(int_result.to_str());

  let float_result = my_min(1.5, 2.5);
  io.println(string.float_to_str(float_result));
  return 0;
}
